from pathlib import Path
import json,html
R=Path(__file__).resolve().parent;L=json.loads((R/'library.json').read_text());templates={t['id']:t for t in L['templates']}
def esc(s):return html.escape(str(s))
def clock(t):return f'{int(t)//60:02}:{t%60:05.2f}'
css='''<style>*{box-sizing:border-box}body{background:#101b22;color:#edf4f4;font:16px/1.55 system-ui;margin:0}main{max-width:1400px;margin:auto;padding:32px 24px}h1{font-size:38px;line-height:1.15}p{max-width:1120px}a{color:#9ddbd3}small{color:#b2c7cb}.tools{position:sticky;top:0;background:#172a34;padding:14px;display:flex;gap:12px;flex-wrap:wrap;z-index:1;border-radius:10px}input,select{font:inherit;padding:10px;background:#f5f4ef;color:#142b32;border-radius:6px;border:0}input{flex:1;min-width:250px}details.entry{margin:18px 0;border:1px solid #3b535b;border-radius:12px;padding:18px;background:#172630}summary{cursor:pointer;font-weight:650;font-size:20px}.states{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.state{background:#223b44;padding:12px;border-radius:8px}img{width:100%;height:auto;background:white;border-radius:5px}blockquote{margin:18px 0;padding:16px;border-left:3px solid #f5ad84;background:#233943}.label{color:#efbd93;font-size:12px;text-transform:uppercase;letter-spacing:.07em}code,pre{font:14px/1.5 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}pre{background:#0c171c;padding:12px;border-radius:6px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:18px}.badge{display:inline-block;padding:3px 10px;border-radius:20px;background:#34535a;margin:5px}.muted{color:#b4c4c8}.hidden{display:none!important}@media(max-width:850px){.states{grid-template-columns:1fr}.meta{grid-template-columns:1fr}}</style>'''
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Original graphics reference library</title>'+css+'<main><h1>Original graphics → narration → teaching templates</h1><p>58 curated examples across the 34:28 source. Original screenshots only: 280 curated state samples and before/during/after windows around all 206 previously identified visual anchors. Reading order, reveal order and teaching purpose are distinct metadata.</p><p><b>Evidence:</b> full frames and graphic-region crops come directly from the source. <b>Interpretation:</b> sentence scaffolds, selection rules and adaptation motion recipes are editorial. Transcript timing is approximate; this is not a claim to annotate every original keyframe.</p><p><a href="https://www.youtube.com/watch?v=HtR5m5VjaDQ">Original video</a> · <a href="library.json">Machine-readable library</a> · <a href="README.md">Usage and coverage</a> · <a href="packets/constrained-web-flow.json">Example image-generation reference packet</a></p><div class="tools"><input id="query" type="search" placeholder="Find a teaching job, example, or transcript phrase"><select id="family"><option value="">All teaching relationships</option>'+''.join(f'<option value="{esc(t["id"])}">{esc(t["id"])}</option>' for t in L['templates'])+'</select><select id="category"><option value="">All source types</option><option>explanatory-graphic-or-overlay</option><option>authentic-ui-evidence</option><option>chapter-navigation</option></select><span id="count"></span></div>']
readme=['# Original-source graphic reference library','', '[Open the searchable review](index.html) · [Machine-readable library](library.json) · [Image-generation packet example](packets/constrained-web-flow.json)','', '58 curated examples, 25 teaching families, 280 curated state samples, and all 206 prior estimated change windows across the 34:28 source. There are 844 unique source-frame times, saved as 1,688 images: full evidence plus graphic-region crops. No failed-reconstruction images are included as references.','', 'The source is 640×360. The graphic crops preserve native resolution and exclude the presenter/caption region. Full frames remain available to inspect context or cropping. Original screenshots/raw transcript are evidence; teaching interpretations, reusable sentence scaffolds and selection rules are editorial. Timing is approximate, not word alignment or original animation keyframes.','', '## A source finding that changes the process','', 'The web/model/results diagram reads left-to-right, but the **model appears first**. The speaker introduces generic models, then web search. The earlier generated pilot incorrectly inferred reveal order from reading direction. Reference selection now records these separately.','', '## Choose a reference by the teaching relationship','', 'Read the target narration, identify what the viewer must understand next, shortlist the relevant relationship, then inspect its source states and transcript. Use a different/custom diagram when none fits. The selector is a curated retrieval tool, not a trained semantic classifier or factual verifier.','', '```bash','python reference-library/select.py --template input-output --instance constrained-web-flow --mode reconstruction --out reference-library/packets/constrained-web-flow.json','```','', 'The output includes `imagegen_request.referenced_image_paths` with original screenshots, a master-image prompt, source observations, sentence scaffolds and selection/misuse rules. View selected original images before using them. After generating the master, derive coherent state images, review their design, reconstruct editable layers, then animate. Do not reuse historical benchmark values or product claims for a new subject.','', '## Template families','']
for t in L['templates']:
 e=next(e for e in L['instances'] if e['id']==t['representative_entry']);ref=e['image_reference_use']['primary_style_anchor'];readme += [f'### {t["id"]}',f'**Relationship:** {t["relationship"]}',f'**Use when:** {t["choose_when"]}',f'**Alternative/misuse:** {t["choose_something_else_when"]}',f'**Sentence scaffold:** `{t["transcript_patterns"][0]}`',f'[Source example and narration](entries/{e["id"]}.md)',f'![Original {t["id"]} reference]({ref})','']
for e in L['instances']:
 t=templates[e['template_id']];obs=e['source_specific_observation'];observed_order=' → '.join(obs.get('observed_reveal_order',[]));search=' '.join([e['label'],e['teaching_intent'],e['relationship'],e['original_transcript'],t['choose_when']]).lower()
 parts.append(f'<details class="entry" data-family="{esc(t["id"])}" data-category="{esc(e["category"])}" data-search="{esc(search)}"><summary>{e["index"]:02}. {esc(e["label"])} · {esc(e["source_timecode"])}</summary><span class="badge">{esc(e["template_id"])}</span><span class="badge">{esc(e["category"])}</span><p><b>Teaching purpose:</b> {esc(e["teaching_intent"])}</p><p><b>Relationship:</b> {esc(e["relationship"])}</p><p><b>Observed reveal order:</b> {esc(observed_order) if observed_order else "See source-state images and sequence observations; a frame-exact object-change order is not yet asserted."}</p><blockquote><b>Original transcript near this graphic (overlapping segments):</b><br>{esc(e["original_transcript"])}</blockquote><div class="meta"><section><h3>Reusable narration scaffolds</h3>'+''.join('<pre>'+esc(x)+'</pre>' for x in t['transcript_patterns'])+'<p><b>Slots:</b> '+esc(', '.join(t['semantic_slots']))+'</p></section><section><h3>Why this graphic, and when to choose another</h3><p>'+esc(t['choose_when'])+'</p><p>'+esc(t['choose_something_else_when'])+'</p><p><b>Adaptation motion grammar:</b> '+esc(t['motion_grammar'])+'</p></section></div><h3>Original state images</h3><div class="states">')
 md=[f'# {e["label"]}','',f'**Source:** [{e["source_timecode"]}]({e["source_video"]}) · **Template:** {e["template_id"]} · **Type:** {e["category"]}','',f'**Teaching purpose:** {e["teaching_intent"]}',f'**Relationship:** {e["relationship"]}','','## Original transcript','', '> '+e['original_transcript'],'','Rolling transcript, approximate times and original transcription errors preserved.','','## Parameterized teaching pattern','']+[f'- `{x}`' for x in t['transcript_patterns']]+['',f'**Use when:** {t["choose_when"]}',f'**Choose another approach when:** {t["choose_something_else_when"]}','',f'**Proposed adaptation motion:** {t["motion_grammar"]}','','## Source-specific reveal evidence','', '```json',json.dumps(obs,indent=2),'```','','## Original source states','']
 for s in e['state_images']:
  img=s['images']['graphic_region'];full=s['images']['full_frame'];quote=' '.join(x['text'] for x in s['nearby_original_transcript']);note=s.get('observed_visual_state',s['sequence_role'])
  parts.append(f'<section class="state"><span class="label">{esc(s["timecode"])}</span><a href="{esc(full)}"><img loading="lazy" src="{esc(img)}" alt="Original source graphic at {esc(s["timecode"])}"></a><p>{esc(note)}</p><small>{esc(quote)}</small></section>')
  md += [f'### {s["timecode"]} — {note}',f'![Original graphic state](../{img})',f'[Full source frame](../{full})',f'> {quote}','']
 parts.append('</div><details><summary>Reading order, reveal order and source observations</summary><pre>'+esc(json.dumps(obs,indent=2))+'</pre><p>'+esc(e['reading_vs_reveal_rule'])+'</p></details>')
 if e['change_windows']:
  parts.append(f'<details><summary>{len(e["change_windows"])} source change windows: before / near transition / after</summary>')
  for w in e['change_windows']:
   parts.append('<h4>Estimated anchor '+clock(w['estimated_anchor'])+'</h4><div class="states">')
   for im in w['source_images']:parts.append('<section class="state"><small>'+esc(im['phase'])+' · '+clock(im['normalized_source_seconds'])+'</small><a href="'+esc(im['full_frame'])+'"><img loading="lazy" src="'+esc(im['graphic_region'])+'"></a></section>')
   parts.append('</div>')
  parts.append('</details>')
 parts.append('<p class="muted">Direct source images; templates are editorial interpretations. Exact spoken triggers, detailed object annotations and micro-transition completeness are not certified.</p><p><a href="entries/'+e['id']+'.json">Entry metadata</a> · <a href="templates/'+t['id']+'.json">Template and source-bound example</a></p></details>')
 if e['change_windows']:
  md += ['<details>',f'<summary>{len(e["change_windows"])} original change windows: before / near transition / after</summary>','']
  for w in e['change_windows']:
   md += ['### Estimated anchor '+clock(w['estimated_anchor']),'','| Before | Near transition | After |','| --- | --- | --- |','| '+' | '.join('!['+im['phase']+'](../'+im['graphic_region']+')' for im in w['source_images'])+' |','', '> '+' '.join(seg['text'] for seg in w['nearby_original_transcript']), '']
  md += ['</details>','']
 (R/'entries'/(e['id']+'.md')).write_text('\n'.join(md))
readme += ['## All source examples','']+[f'- [{e["source_timecode"]} — {e["label"]}](entries/{e["id"]}.md)' for e in L['instances']]
readme += ['', '## Limits and provenance','','Not every sampled frame is a distinct conceptual state; reading holds are evidence too. Prior anchor windows are approximate and may show no obvious change. Some source camera moves deliberately crop objects at the edge; inspect the linked full frame. Original motion is inferred from multiple source screenshots and prior dense evidence, not reconstructed as original keyframes. This library does not certify product availability, accuracy claims, author permissions or the factual truth of a new script.','', 'Primary source: https://www.youtube.com/watch?v=HtR5m5VjaDQ. User-supplied video files; source SHA-256 and deterministic extraction details are recorded in `library.json`.']
parts.append('''</main><script>const q=document.querySelector('#query'),f=document.querySelector('#family'),c=document.querySelector('#category');function filter(){let n=0;for(const e of document.querySelectorAll('.entry')){const ok=(!f.value||e.dataset.family===f.value)&&(!c.value||e.dataset.category===c.value)&&(!q.value||e.dataset.search.includes(q.value.toLowerCase()));e.classList.toggle('hidden',!ok);if(ok)n++}document.querySelector('#count').textContent=n+' / 58 examples'}q.addEventListener('input',filter);f.addEventListener('change',filter);c.addEventListener('change',filter);filter();</script></html>''')
(R/'index.html').write_text(''.join(parts));(R/'README.md').write_text('\n'.join(readme));print('Source library review, 58 annotated source pages and 25 families exported')
